    #[test]
    fn generate_langgraph_json_disables_studio_auth_for_local_builds() {
        // The dev server grants Studio identity on `x-auth-scheme: langsmith`
        // with no credential check, and `MDA_LOCAL_DEV` already unscopes local
        // Studio, so local builds must turn the scheme off.
        let out = generate_langgraph_json(&LanggraphManifestInputs {
            graph: "./_mda_entry.py:agent",
            language: Language::Python,
            api_version: LANGGRAPH_API_VERSION,
            python_version: PYTHON_VERSION,
            auth_path: Some("./_mda_auth.py:auth"),
            managed_http_path: None,
            assistant_id: "agent",
            include_vendored_runtime: false,
            local_packages: &[],
            disable_studio_auth: true,
            extra_graphs: &[],
        })
        .unwrap();

        let value: serde_json::Value =
            serde_json::from_str(&out).expect("generated langgraph.json must be valid JSON");
        assert_eq!(value["auth"]["disable_studio_auth"], true);
    }

    #[test]
    fn generate_langgraph_json_adds_auth_block_when_identity_present() {
        let out = generate_langgraph_json(&LanggraphManifestInputs {
            graph: "./_mda_entry.py:agent",
            language: Language::Python,
            api_version: LANGGRAPH_API_VERSION,
            python_version: PYTHON_VERSION,
            auth_path: Some("./_mda_auth.py:auth"),
            managed_http_path: None,
            assistant_id: "agent",
            include_vendored_runtime: false,
            local_packages: &[],
            disable_studio_auth: false,
            extra_graphs: &[],
        })
        .unwrap();

        let value: serde_json::Value =
            serde_json::from_str(&out).expect("generated langgraph.json must be valid JSON");
        assert_eq!(value["auth"]["path"], "./_mda_auth.py:auth");
        assert_eq!(value["auth"]["disable_studio_auth"], false);
        assert_eq!(
            value["http"]["configurable_headers"]["includes"],
            serde_json::json!(["x-mda-user-id",])
        );
        assert_eq!(value["http"]["middleware_order"], "auth_first");
        // The ingress secret must never be allowlisted into config.configurable.
        let includes = value["http"]["configurable_headers"]["includes"]
            .as_array()
            .unwrap();
        assert!(!includes
            .iter()
            .any(|header| header == "x-mda-ingress-secret"));
    }
